        assert isinstance(fl_M_pas_inv, FiberForceLengthPassiveInverseDeGroote2016)
        assert str(fl_M_pas_inv) == 'FiberForceLengthPassiveInverseDeGroote2016(fl_M_pas, c_0, c_1)'

